export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;

export type BoardSize = (typeof BOARD_SIZES)[number];

export interface Board {
  readonly code: string;
  readonly size: BoardSize;
  readonly seed: number;
}

const MIN_SEED = 1;
const MAX_SEED = 2_147_483_646;
const CODE_PATTERN = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/;

export function isBoardSize(value: unknown): value is BoardSize {
  return typeof value === "number" && BOARD_SIZES.some((size) => size === value);
}

export function parseBoardCode(text: string): Board | null {
  const match = CODE_PATTERN.exec(text);
  if (match === null) return null;
  const sizeText = match[1];
  const seedText = match[2];
  if (sizeText === undefined || seedText === undefined) return null;
  const size = Number(sizeText);
  const seed = Number(seedText);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed)) return null;
  if (seed < MIN_SEED || seed > MAX_SEED) return null;
  return { code: text, size, seed };
}
import type { Board } from "./boardCode.ts";

const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const PARK_MILLER_RANGE = PARK_MILLER_MODULUS - 1;

export function createDeck(board: Board): readonly number[] {
  const count = board.size * board.size;
  const deck = Array.from({ length: count }, (_, index) => Math.floor(index / 2));
  let state = board.seed;

  for (let index = count - 1; index > 0; index -= 1) {
    const limit = Math.floor(PARK_MILLER_RANGE / (index + 1)) * (index + 1);
    let value = limit;
    while (value >= limit) {
      state = (state * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
      value = state - 1;
    }
    const otherIndex = value % (index + 1);
    const current = deck[index];
    const other = deck[otherIndex];
    if (current === undefined || other === undefined) continue;
    deck[index] = other;
    deck[otherIndex] = current;
  }

  return Object.freeze(deck);
}
