function makeGame(code: string): GameState {
  const game = createGame(code);
  if (game === null) throw new Error("A session created an invalid board code.");
  return game;
}

function freshSeed(excluding?: number): number {
  let seed: number;
  try {
    const values = new Uint32Array(1);
    crypto.getRandomValues(values);
    seed = (values[0] ?? 0) % MAX_SEED + 1;
  } catch {
    seed = Math.floor(Math.random() * MAX_SEED) + 1;
  }
  if (seed === excluding) return seed === MAX_SEED ? 1 : seed + 1;
  return seed;
}

function freshGame(size: BoardSize, excluding?: number): GameState {
  return makeGame(`np1-${size}-${freshSeed(excluding)}`);
}

function initialSession(): SessionState {
  const preferences = readPreferences();
  return {
    game: freshGame(preferences.size), paused: false, revision: 0,
    celebrationId: null, preferences, event: { id: 0, text: "" }, status: null,
  };
}

function clockCanRun(session: SessionState): boolean {
  return session.game.started && !session.paused && !isWon(session.game) && !document.hidden;
}

export function useSession(): GameSession {
  const [session, setSession] = useState(initialSession);
  const stateRef = useRef(session);
  const eventId = useRef(0);
  const clockSample = useRef<number | null>(null);
  const clockActive = useRef(false);
  const syncRef = useRef<() => void>(() => undefined);
  const [visibilityRevision, setVisibilityRevision] = useState(0);

  const commit = (next: SessionState): void => {
    stateRef.current = next;
    clockActive.current = clockCanRun(next);
    setSession(next);
  };

  const makeEvent = (text: string): SessionEvent => {
    eventId.current += 1;
    return { id: eventId.current, text };
  };

  const syncClock = (): void => {
    const now = performance.now();
    const previous = stateRef.current;
    const active = clockActive.current;
    const delta = clockSample.current === null ? 0 : Math.max(0, now - clockSample.current);
    clockSample.current = now;
    clockActive.current = clockCanRun(previous);
    if (!active || delta <= 0) return;
    const game = advanceGame(previous.game, delta);
    if (game !== previous.game) commit({ ...previous, game });
  };
  syncRef.current = syncClock;

  useEffect(() => {
    clockSample.current = performance.now();
    clockActive.current = clockCanRun(stateRef.current);
    const onVisibilityChange = (): void => {
      syncRef.current();
      setVisibilityRevision((revision) => revision + 1);
    };
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => document.removeEventListener("visibilitychange", onVisibilityChange);
  }, []);

  useEffect(() => {
    const { game, paused } = session;
    if (paused || document.hidden || !game.started || isWon(game)) return;
    if (game.elapsedMs >= MAX_ELAPSED_MS && game.selection.kind !== "mismatch") return;
    const nextSecond = 1000 - (game.elapsedMs % 1000);
    const mismatchEnd = game.selection.kind === "mismatch" ? game.selection.remainingMs : Infinity;
    const delay = Math.max(1, Math.ceil(Math.min(nextSecond, mismatchEnd)));
    const timeout = window.setTimeout(() => syncRef.current(), delay);
    return () => window.clearTimeout(timeout);
  }, [session.game, session.paused, visibilityRevision]);

  const activateCard = (index: number): void => {
    syncClock();
    const previous = stateRef.current;
    if (previous.paused) return;
    const game = applyCard(previous.game, index);
    if (game === previous.game) return;

    const text = turnAnnouncement(previous.game, game);
    const winningTurn = !isWon(previous.game) && isWon(game);
    let preferences = previous.preferences;
    if (winningTurn) {
      const oldBest = preferences.bestMoves[game.board.size];
      if (oldBest === undefined || game.moves < oldBest) {
        preferences = {
          size: game.board.size,
          bestMoves: Object.freeze({ ...preferences.bestMoves, [game.board.size]: game.moves }),
        };
        writePreferences(preferences);
      }
    }
    commit({
      ...previous, game, preferences,
      celebrationId: winningTurn ? eventId.current + 1 : previous.celebrationId,
      event: text === null ? previous.event : makeEvent(text),
    });
  };

  const startGame = (game: GameState, preferences = stateRef.current.preferences): void => {
    const previous = stateRef.current;
    commit({ ...previous, game, preferences, paused: false, revision: previous.revision + 1,
