  }));
  expect(uniqueArtwork.size).toBe(128);

  const styles = await page.evaluate(() => Array.from(document.styleSheets)
    .map((sheet) => Array.from(sheet.cssRules).map((rule) => rule.cssText).join("\n"))
    .join("\n"));
